sys_ws_operation.operation_script:
(function process(request, response) {
    var suggestionSysId = request.pathParams.suggestion_sys_id;
    if (!suggestionSysId) {
        response.setStatus(400);
        response.setBody({ error: 'suggestion_sys_id is required' });
        return;
    }

    var gr = new GlideRecord('x_2319800_deskma_0_ai_suggestion');
    if (!gr.get(suggestionSysId)) {
        response.setStatus(404);
        response.setBody({ error: 'Suggestion not found' });
        return;
    }

    gr.setValue('status', 'accepted');
    gr.setValue('processed_at', new GlideDateTime().toString());
    gr.update();

    var incidentGr = new GlideRecord('incident');
    if (incidentGr.get(gr.getValue('incident'))) {
        var sugType = gr.getValue('suggestion_type');
        if (sugType === 'category') {
            incidentGr.setValue('category', gr.getValue('suggested_category'));
        } else if (sugType === 'assignment_group') {
            incidentGr.setValue('assignment_group', gr.getValue('suggested_assignment_group'));
        } else if (sugType === 'resolution_notes') {
            incidentGr.setValue('close_notes', gr.getValue('suggested_resolution_notes'));
        }
        incidentGr.update();
    }

    response.setStatus(200);
    response.setBody({
        result: {
            sys_id: gr.getUniqueValue(),
            status: 'accepted',
            suggestion_type: gr.getValue('suggestion_type'),
            message: 'Suggestion accepted and applied to incident'
        }
    });
})(request, response)
